165	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
166	     */
167	    @Transient
168	    public String getInitials() {
169	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
170	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
171	    }
172	
173	    /**
174	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
175	     * YY is the last two digits of the registration date's year
176	     * (e.g. {@code "TOW-SMI-0007-M26"}). Derived from the owner's own fields; null when
177	     * either the customer code or registration date is absent.
178	     */
179	    @Transient
180	    public String getMembershipNumber() {
181	        if (this.customerCode == null || this.registrationDate == null) {
182	            return null;
183	        }
184	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
185	    }
186	
187	    /**
188	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
189	     * contained in the {@code customerCode}, scanning right to left and doubling the
190	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
191	     * own fields; null when the customer code is absent.
192	     */
193	    @Transient
194	    public Integer getCheckDigit() {
195	        if (this.customerCode == null) {
196	            return null;
197	        }
198	        int sum = 0;
199	        boolean dbl = true;
200	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
201	            char c = this.customerCode.charAt(i);
202	            if (c < '0' || c > '9') {
203	                continue;
204	            }
205	            int d = c - '0';
206	            if (dbl) {
207	                d *= 2;
208	                if (d > 9) {
209	                    d -= 9;
210	                }
211	            }
212	            sum += d;
213	            dbl = !dbl;
214	        }
215	        return (10 - (sum % 10)) % 10;
216	    }
217	
218	    /**
219	     * The owner's membership level: a number from 1 to 3 assigned at creation. Starts
220	     * at 1, gains 1 when an email address is present, gains a further 1 when the owner
221	     * has no namesakes ({@code namesakeCount} is 0), and is capped at 3 (level 4 is
222	     * reserved for tenure). Derived from the owner's own fields.
223	     */
224	    @Transient
225	    public Integer getMembershipLevel() {
226	        int level = 1;
227	        boolean hasEmail = this.email != null && !this.email.isBlank();
228	        if (hasEmail) {
229	            level++;
230	        }
231	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
232	        if (unique) {
233	            level++;
234	        }
235	        return Math.min(level, 3);
236	    }
237	
238	    /**
239	     * Fixed city-to-region lookup table. Any city not listed derives locality
240	     * {@code "UNKNOWN"}.
241	     */
242	    private static final Map<String, String> CITY_REGION = Map.of(
243	        "Sydney", "NSW",
244	        "Melbourne", "VIC",
245	        "Brisbane", "QLD");
246	
247	    /**
248	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
249	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
250	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
251	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
252	     * postcode validation).
253	     */
254	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
255	        "NSW", new int[] {2000, 2099},
256	        "VIC", new int[] {3000, 3099},
257	        "QLD", new int[] {4000, 4099});
258	
259	    /**
260	     * The owner's locality: the canonical region derived by preferring the postcode
261	     * range ({@code 2000-2099->NSW}, {@code 3000-3099->VIC}, {@code 4000-4099->QLD}),
262	     * falling back to the fixed city-to-region table ({@code Sydney->NSW},
263	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}) when the postcode is absent or in
264	     * no known range, or {@code "UNKNOWN"} when neither resolves. Derived from the
265	     * owner's own fields.
266	     */
267	    @Transient
268	    public String getLocality() {
269	        return region(this.city, this.postcode);
270	    }
271	
272	    /**
273	     * The canonical region derived by preferring the postcode range over the city.
274	     * Looks the postcode up against the known ranges first (NSW 2000-2099,
275	     * VIC 3000-3099, QLD 4000-4099); only when the postcode is absent or in no known
276	     * range does it fall back to the fixed city-to-region table. Returns
277	     * {@code "UNKNOWN"} when neither resolves. The single source of truth for region
278	     * derivation, so a known city still yields its region while cities that share a
279	     * name are disambiguated by postcode.
280	     */
281	    public static String region(String city, String postcode) {
282	        String byPostcode = regionForPostcode(postcode);
283	        return byPostcode != null ? byPostcode : regionForCity(city);
284	    }
285	
286	    /**
287	     * The canonical region for a city per the fixed city-to-region table
288	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
289	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
290	     * for the city-to-region mapping, used as the fallback in
291	     * {@link #region(String, String)} and as the city's region in postcode validation.
292	     */
293	    public static String regionForCity(String city) {
294	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
295	    }
296	
297	    /**
298	     * The canonical region for a 4-digit postcode per the fixed range table
299	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
300	     * is absent, not a well-formed integer, or in no known range. Reads the shared
301	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #region(String, String)}
302	     * for locality derivation and by postcode validation to range-check a submitted
303	     * postcode against its city's region.
304	     */
305	    public static String regionForPostcode(String postcode) {
306	        if (postcode == null) {
307	            return null;
308	        }
309	        int value;
310	        try {
311	            value = Integer.parseInt(postcode.trim());
312	        } catch (NumberFormatException ex) {
313	            return null;
314	        }
315	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
316	            int[] range = entry.getValue();
317	            if (value >= range[0] && value <= range[1]) {
318	                return entry.getKey();
319	            }
320	        }
321	        return null;
322	    }
323	
324	    /**
325	     * Whether the region is subject to postcode range validation, i.e. has a known
326	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
327	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
328	     */
329	    public static boolean hasPostcodeRange(String region) {
330	        return REGION_POSTCODE_RANGES.containsKey(region);
331	    }
332	
333	    /**
334	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
335	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
336	     */
337	    @Transient
338	    public String getContactPreference() {
339	        boolean hasEmail = this.email != null && !this.email.isBlank();
340	        return hasEmail ? "EMAIL" : "PHONE";
341	    }
342	
343	    /**
344	     * The owner's identity key: the single value that duplicate detection is expressed
345	     * through, formed as {@code normalizedTelephone + "|" + (email or empty) + "|" +
346	     * (householdId or empty)}. The telephone and email are already stored in their
347	     * normalized forms (E.164 and lower-cased), and the household id is empty for a solo
348	     * owner. Two owners are duplicates only when their whole identity keys are equal, so
349	     * two members of the same household with different telephones have distinct keys.
350	     * Derived from the owner's own fields.
351	     */
352	    @Transient
353	    public String getIdentityKey() {
354	        return identityKey(this.telephone, this.email, this.householdId);
355	    }
356	
357	    /**
358	     * Composes an identity key from its already-normalized parts. The single place the
359	     * key's shape is defined, so the create-time duplicate check (which normalizes a
360	     * request's parts) and this entity's {@link #getIdentityKey()} cannot drift apart. A
361	     * null or blank part contributes an empty segment.
362	     */
363	    public static String identityKey(String normalizedTelephone, String normalizedEmail, String householdId) {
364	        return keyPart(normalizedTelephone) + "|" + keyPart(normalizedEmail) + "|" + keyPart(householdId);
365	    }
366	
367	    private static String keyPart(String value) {
368	        return (value == null || value.isBlank()) ? "" : value;
369	    }
370	
371	    protected Set<Pet> getPetsInternal() {
372	        if (this.pets == null) {
373	            this.pets = new HashSet<>();
374	        }
375	        return this.pets;
376	    }
377	
378	    protected void setPetsInternal(Set<Pet> pets) {
379	        this.pets = pets;
380	    }
381	
382	    public List<Pet> getPets() {
383	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
384	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
385	        return Collections.unmodifiableList(sortedPets);
386	    }
387	
388	    public void setPets(List<Pet> pets) {
389	        this.pets = new HashSet<>(pets);
390	    }
391	
392	    public void addPet(Pet pet) {
393	        getPetsInternal().add(pet);
394	        pet.setOwner(this);
395	    }
396	
397	    /**
398	     * Return the Pet with the given name, or null if none found for this Owner.
399	     *
400	     * @param name to test
401	     * @return true if pet name is already in use
402	     */
403	    public Pet getPet(String name) {
404	        return getPet(name, false);
405	    }
406	
407	    /**
408	     * Return the Pet with the given name, or null if none found for this Owner.
409	     *
410	     * @param name to test
411	     * @return true if pet name is already in use
412	     */
413	    public Pet getPet(String name, boolean ignoreNew) {
414	        name = name.toLowerCase();
415	        for (Pet pet : getPetsInternal()) {
416	            if (!ignoreNew || !pet.isNew()) {
417	                String compName = pet.getName();
418	                compName = compName.toLowerCase();
419	                if (compName.equals(name)) {
420	                    return pet;
421	                }
422	            }
423	        }
424	        return null;
425	    }
426	
427	    public Pet getPet(Integer petId) {
428	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
429	    }
430	
431	    @Override
432	    public String toString() {
433	        return new ToStringCreator(this)
434	
435	            .append("id", this.getId())
436	            .append("new", this.isNew())
437	            .append("lastName", this.getLastName())
438	            .append("firstName", this.getFirstName())
439	            .append("address", this.address)
440	            .append("city", this.city)
441	            .append("telephone", this.telephone)
442	            .append("email", this.email)
443	            .toString();
444	    }
445	}
