1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Single source of truth for what a "normalized" owner telephone is: the number in
5	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form. Used by
6	 * {@link NormalizeOwnerTelephone} when storing and by {@link EnsureUniqueIdentity} when
7	 * forming the telephone part of an owner's identity key, so the rule cannot drift between
8	 * the two steps.
9	 *
10	 * <p>The rule: spaces, dashes and brackets are stripped. If a leading {@code '+'} (and
11	 * therefore an explicit country code) is present it is kept; otherwise country code
12	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
13	 * digits. The result must have 8 to 15 digits after the {@code '+'}, and for a recognized
14	 * country code the national number must have the exact length that country requires
15	 * ({@code '+61'} => 9 national digits, {@code '+1'} => 10), else it is invalid.
16	 */
17	final class OwnerTelephones {
18	
19	    private OwnerTelephones() {
20	    }
21	
22	    /**
23	     * Returns the E.164 form of {@code telephone}, or {@code null} if it cannot form a
24	     * valid E.164 number (non-digit characters remaining, not 8-15 digits after the
25	     * {@code '+'}, or a wrong national-number length for a recognized country code).
26	     */
27	    static String toE164(String telephone) {
28	        if (telephone == null) {
29	            return null;
30	        }
31	        String trimmed = telephone.trim();
32	        boolean explicitCountryCode = trimmed.startsWith("+");
33	        // Strip spaces, dashes and brackets; keep a leading '+' and the digits.
34	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
35	        String digits = explicitCountryCode ? stripped.substring(1) : stripped;
36	        if (!digits.matches("\\d+")) {
37	            return null;
38	        }
39	        if (!explicitCountryCode) {
40	            // No country code: assume +61 and drop a single leading national '0'.
41	            if (digits.startsWith("0")) {
42	                digits = digits.substring(1);
43	            }
44	            digits = "61" + digits;
45	        }
46	        if (digits.length() < 8 || digits.length() > 15) {
47	            return null;
48	        }
49	        if (!hasValidNationalLength(digits)) {
50	            return null;
51	        }
52	        return "+" + digits;
53	    }
54	
55	    /**
56	     * Checks the national-number length against the country code: {@code '+61'} requires
57	     * exactly 9 national digits and {@code '+1'} exactly 10. Unrecognized country codes are
58	     * accepted on the general 8-15 digit rule alone.
59	     */
60	    private static boolean hasValidNationalLength(String digits) {
61	        if (digits.startsWith("61")) {
62	            return digits.length() - 2 == 9;
63	        }
64	        if (digits.startsWith("1")) {
65	            return digits.length() - 1 == 10;
66	        }
67	        return true;
68	    }
69	}
