4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate check on create: rejects a new owner only when its whole
11	 * identity key equals an existing owner's. The identity key is
12	 * {@code normalizedTelephone + "|" + (email or empty) + "|" + (householdId or empty)}
13	 * (see {@link Owner#identityKey}), so the former separate telephone, email and household
14	 * checks are now expressed through this one key.
15	 *
16	 * <p>The request already carries the E.164 telephone (from {@link NormalizeOwnerTelephone})
17	 * and the normalized address (from {@link NormalizeOwnerAddress}); the email is
18	 * canonicalized here via {@link OwnerEmails} to the form {@link BuildOwner} will store,
19	 * and the household id is the one {@link AssignHousehold} would assign when the request
20	 * opts into a shared household (otherwise empty). Because the telephone is part of the
21	 * key, two members of the same household with different telephones have distinct keys and
22	 * are both allowed; only an exact full-key match is a 409 via
23	 * {@link DuplicateIdentityException}.
24	 */
25	public class EnsureUniqueIdentity {
26	
27	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws DuplicateIdentityException {
29	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
30	                ? Households.householdId(request.getLastName(), request.getAddress())
31	                : null;
32	        String identityKey = Owner.identityKey(OwnerTelephones.toE164(request.getTelephone()),
33	                OwnerEmails.normalize(request.getEmail()), householdId);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (identityKey.equals(existing.getIdentityKey())) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
