3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Single source of truth for what a "household" is: two owners share one when their
12	 * last name and address match after normalization. The last name is trimmed, has runs
13	 * of whitespace collapsed to a single space and is lower-cased; the address uses the
14	 * canonical {@link OwnerAddresses} normalization (the same form that is stored and
15	 * returned), so the comparison always runs on the normalized address. Also derives the
16	 * stable {@code householdId} for a household, used both when {@link AssignHousehold}
17	 * joins an owner to one and when the create-time duplicate check builds an owner's
18	 * identity key, so the two cannot drift apart.
19	 */
20	final class Households {
21	
22	    private Households() {
23	    }
24	
25	    /** Lower-cases and collapses runs of whitespace to a single space so the comparison
26	     *  ignores case and incidental spacing differences. */
27	    static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
32	    }
33	
34	    /** The canonical normalized address (see {@link OwnerAddresses}), used for every
35	     *  address comparison so it matches the stored and returned form. Never null. */
36	    static String normalizeAddress(String value) {
37	        String normalized = OwnerAddresses.normalize(value);
38	        return normalized == null ? "" : normalized;
39	    }
40	
41	    /** Whether {@code existing} belongs to the household identified by the already
42	     *  normalized {@code lastName} and {@code address}. */
43	    static boolean matches(Owner existing, String normalizedLastName, String normalizedAddress) {
44	        return normalizedLastName.equals(normalize(existing.getLastName()))
45	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()));
46	    }
47	
48	    /** The {@code householdId} for the household an owner with this last name and address
49	     *  belongs to, derived from the raw values (normalized here first). */
50	    static String householdId(String rawLastName, String rawAddress) {
51	        return deriveHouseholdId(normalize(rawLastName), normalizeAddress(rawAddress));
52	    }
53	
54	    /** Stable identifier for a household: the first 12 upper-case hex characters of the
55	     *  SHA-256 of the already-normalized last name and address joined by a NUL separator. */
56	    static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest((normalizedLastName + "\u0000" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder(digest.length * 2);
61	            for (byte b : digest) {
62	                sb.append(String.format("%02x", b));
63	            }
64	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException("SHA-256 not available", ex);
68	        }
69	    }
70	}
