3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When the request sets {@code sharesHousehold} true, joins the new owner to the
10	 * household formed by owners that share the same last name and address, using the
11	 * shared comparison in {@link Households} so the {@code householdId} it assigns matches
12	 * the one {@link EnsureUniqueIdentity} folds into the identity key.
13	 *
14	 * <p>Every owner in a household carries the same {@code householdId} — a stable
15	 * identifier derived from the normalized last name and address, so all members
16	 * compute the same value independently. The new owner receives it, and any existing
17	 * household members that do not yet carry it are back-filled so the whole household
18	 * shares one identifier.
19	 *
20	 * <p>Does nothing when {@code sharesHousehold} is absent or false, leaving a solo
21	 * owner's {@code householdId} null.
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	        String lastName = Households.normalize(owner.getLastName());
30	        String address = Households.normalizeAddress(owner.getAddress());
31	        String householdId = Households.deriveHouseholdId(lastName, address);
32	        owner.setHouseholdId(householdId);
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (Households.matches(existing, lastName, address)
35	                    && !householdId.equals(existing.getHouseholdId())) {
36	                existing.setHouseholdId(householdId);
37	                ownerRepository.save(existing);
38	            }
39	        }
40	    }
41	}
