1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share
11	 * the same first name and last name, compared case-insensitively. Runs before the owner
12	 * is saved, so the count reflects the existing owners only (not the owner being created).
13	 */
14	public class CountNamesakes {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = normalize(owner.getFirstName());
18	        String lastName = normalize(owner.getLastName());
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (firstName.equals(normalize(existing.getFirstName()))
22	                    && lastName.equals(normalize(existing.getLastName()))) {
23	                count++;
24	            }
25	        }
26	        owner.setNamesakeCount(count);
27	    }
28	
29	    private static String normalize(String value) {
30	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
31	    }
32	}
