1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for what a "normalized" owner address is. Used by
8	 * {@link NormalizeOwnerAddress} when storing and returning the value, and by
9	 * {@link Households} when comparing addresses for household duplicate detection and the
10	 * shared household id, so the rule cannot drift between storing and comparing.
11	 *
12	 * <p>The rule: the value is trimmed, runs of whitespace are collapsed to a single space
13	 * and the whole value is upper-cased; then each whitespace-separated token that is a
14	 * common street-type abbreviation is expanded to its full form ({@code ST -> STREET},
15	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is the canonical address;
16	 * it is empty when the input was blank (only whitespace).
17	 */
18	final class OwnerAddresses {
19	
20	    /** Common street-type abbreviations expanded to their full upper-case form. */
21	    private static final Map<String, String> ABBREVIATIONS = Map.of(
22	            "ST", "STREET",
23	            "RD", "ROAD",
24	            "AVE", "AVENUE");
25	
26	    private OwnerAddresses() {
27	    }
28	
29	    /**
30	     * Returns the normalized form of {@code address}: trimmed, whitespace collapsed,
31	     * upper-cased and with common abbreviations expanded. Returns {@code null} for a
32	     * {@code null} input and an empty string for an input that is blank after trimming.
33	     */
34	    static String normalize(String address) {
35	        if (address == null) {
36	            return null;
37	        }
38	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
39	        if (collapsed.isEmpty()) {
40	            return "";
41	        }
42	        String[] tokens = collapsed.split(" ");
43	        StringBuilder sb = new StringBuilder(collapsed.length());
44	        for (int i = 0; i < tokens.length; i++) {
45	            if (i > 0) {
46	                sb.append(' ');
47	            }
48	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
49	        }
50	        return sb.toString();
51	    }
52	}
